// Build inputs are generated by npm run release:private; this script never uploads.
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dist = path.join(root, "dist");
const manifest = JSON.parse(fs.readFileSync(path.join(dist, "manifest.json"), "utf8"));
const sourceManifest = JSON.parse(fs.readFileSync(path.join(root, "manifest.json"), "utf8"));
if (JSON.stringify(manifest) !== JSON.stringify(sourceManifest)) throw new Error("Build the current source before packaging.");
if (manifest.manifest_version !== 3 || !/^\d+\.\d+\.\d+(?:\.\d+)?$/.test(manifest.version)) throw new Error("Invalid release manifest.");
if (manifest.host_permissions.some(host => !["https://jobs.apple.com/*", "https://www.apple.com/careers/*", "https://api.openai.com/*"].includes(host))) {
  throw new Error("Review unexpected host permissions before preparing the Apple-only release.");
}
const allowed = new Set(["assets", "background.js", "content.js", "icons", "lib", "manifest.json", "PRIVACY.md", "sidepanel.html"]);
const files = [];
function collect(relative = "") {
  for (const name of fs.readdirSync(path.join(dist, relative)).sort()) {
    if (!relative && !allowed.has(name)) throw new Error(`Unexpected release entry: ${name}`);
    const next = path.posix.join(relative, name);
    const stat = fs.lstatSync(path.join(dist, next));
    if (stat.isSymbolicLink()) throw new Error(`Release must not contain symbolic links: ${next}`);
    if (stat.isDirectory()) collect(next);
    else if (stat.isFile()) files.push(next);
    else throw new Error(`Unexpected release file type: ${next}`);
  }
}
collect();
const required = ["manifest.json", "sidepanel.html", "background.js", "content.js", "PRIVACY.md",
  "lib/appleJobStore.js", "lib/appleWithdrawalRecovery.js", "lib/appleWithdrawalSafety.js", "assets/sidepanel.js"];
for (const file of required) if (!files.includes(file)) throw new Error(`Missing release file: ${file}`);
// The plain runtime scripts and policy are copied verbatim, never bundled away.
for (const file of files.filter(file => !file.startsWith("assets/") && file !== "sidepanel.html")) {
  if (!fs.readFileSync(path.join(dist, file)).equals(fs.readFileSync(path.join(root, file)))) {
    throw new Error(`Stale build file: ${file}`);
  }
}
const digest = value => crypto.createHash("sha256").update(value).digest("hex");
const outDir = path.join(root, "release");
fs.mkdirSync(outDir, { recursive: true });
const stem = `career-peeler-${manifest.version}-private-beta`;
const zipFile = path.join(outDir, `${stem}.zip`);
// Always create a new archive: updating an older ZIP could retain deleted files.
fs.rmSync(zipFile, { force: true });
execFileSync("zip", ["-X", "-q", zipFile, ...files], { cwd: dist, stdio: "pipe" });
execFileSync("unzip", ["-t", zipFile], { stdio: "pipe" });
const entries = execFileSync("unzip", ["-Z1", zipFile], { encoding: "utf8" }).trim().split("\n").sort();
if (JSON.stringify(entries) !== JSON.stringify([...files].sort())) throw new Error("ZIP contents differ from the verified build.");
let baseCommit = null, trackedChanges = null;
try {
  baseCommit = execFileSync("git", ["rev-parse", "HEAD"], { cwd: root, encoding: "utf8" }).trim();
  trackedChanges = Boolean(execFileSync("git", ["status", "--porcelain", "--untracked-files=no"], { cwd: root, encoding: "utf8" }).trim());
} catch {}
const checksum = digest(fs.readFileSync(zipFile));
const materialsDir = path.join(outDir, `career-peeler-${manifest.version}-store-materials`);
fs.mkdirSync(materialsDir, { recursive: true });
for (const [from, to] of [
  ["PRIVACY.md", "PRIVACY.md"], ["store-assets/PRIVATE_LISTING.md", "PRIVATE_LISTING.md"],
  ["docs/releases/PRIVATE_RELEASE.md", "PRIVATE_RELEASE.md"],
  ...fs.readdirSync(path.join(root, "store-assets")).filter(file => file.endsWith(".png")).map(file => [`store-assets/${file}`, file])
]) fs.copyFileSync(path.join(root, from), path.join(materialsDir, to));
const record = { version: manifest.version, preparedAt: new Date().toISOString(),
  status: "prepared-not-published", baseCommit, trackedChanges, archive: path.basename(zipFile), sha256: checksum,
  bytes: fs.statSync(zipFile).size, storeMaterials: path.basename(materialsDir),
  files: Object.fromEntries(files.map(file => [file, digest(fs.readFileSync(path.join(dist, file)))])) };
fs.writeFileSync(path.join(outDir, `${stem}.json`), JSON.stringify(record, null, 2) + "\n");
fs.writeFileSync(path.join(outDir, `${stem}.zip.sha256`), `${checksum}  ${path.basename(zipFile)}\n`);
process.stdout.write(`Prepared ${path.relative(root, zipFile)} (${record.bytes} bytes, ${files.length} files)\nSHA-256: ${checksum}\nNo upload or publication performed.\n`);
